namespace Net7ClientManager.Navigation;

using System.IO.Compression;
using System.Text.Json;
using System.Text.Json.Serialization;

/// <summary>
/// Generated runtime payload for GalaxyNavigationCatalog.json. The JSON file
/// remains the human-readable audit source; this compressed copy avoids a
/// runtime content-file dependency.
/// </summary>
internal static class GalaxyNavigationCatalogData
{
    private static readonly JsonSerializerOptions jsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        Converters =
        {
            new JsonStringEnumConverter(),
        },
    };

    public static GalaxyNavigationCatalog Create(
        GalaxyTopology topology)
    {
        ArgumentNullException.ThrowIfNull(topology);
        var compressed = Convert.FromBase64String(
            CompressedCatalogBase64);

        using var input = new MemoryStream(compressed);
        using var gzip = new GZipStream(
            input,
            CompressionMode.Decompress);
        using var output = new MemoryStream();

        gzip.CopyTo(output);

        var document = JsonSerializer.Deserialize<
            GalaxyNavigationCatalogDocument>(
            output.ToArray(),
            jsonOptions) ??
            throw new InvalidOperationException(
                "The built-in navigation catalog is empty.");

        document = document with
        {
            Sectors =
            [
                .. document.Sectors
                    .Where(sector => topology.TryGetByKey(
                        sector.SectorKey,
                        out _))
                    .Select(sector => sector with
                    {
                        Departures =
                        [
                            .. sector.Departures.Where(departure =>
                                string.IsNullOrWhiteSpace(
                                    departure.ToSectorKey) ||
                                topology.TryGetByKey(
                                    departure.ToSectorKey,
                                    out _)),
                        ],
                    }),
            ],
        };

        return new GalaxyNavigationCatalog(
            topology,
            document);
    }

